play_order":3},{"passage_title":"El caso de las 9:17","record_type":"message","occurred_at":"Comparación de fuentes","title":"Pista: actividad posterior al cierre","body":"El testimonio relatado del empleado de mantenimiento y la entrada 4589 son compatibles con actividad después de las 21:30. El expediente no demuestra que ambos describan el mismo movimiento ni identifica a quien lo realizó.","source":"Comparación de la lectura con el libro de equipajes","sender":"Análisis documental","recipient":"","subject":"","suspect_name":null,"evidence_title":null,"evidence_code":"REG-4589","document_reference":"REG-4589 · contraste","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"RESERVADO","display_order":4},{"passage_title":"El caso de las 9:17","record_type":"timeline","occurred_at":"Antes de las 21:30","title":"Cierre declarado de la zona de equipajes","body":"Julián Herrera afirmó haber cerrado la zona antes de las 21:30 y que después no hubo ingresos ni movimientos de equipaje.","source":"Declaración de Julián Herrera","sender":"Julián Herrera","recipient":"","subject":"","suspect_name":null,"evidence_title":null,"evidence_code":"","document_reference":"","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"RESERVADO","display_order":1},{"passage_title":"El caso de las 9:17","record_type":"timeline","occurred_at":"21:17","title":"Hora aparente en la fotografía","body":"El reloj de la estación parece marcar las 21:17. La imagen por sí sola no demuestra cuándo se tomó ni que el reloj estuviera correctamente ajustado.","source":"Fotografía recuperada de la estación","sender":"Archivo fotográfico","recipient":"","subject":"","suspect_name":null,"evidence_title":null,"evidence_code":"FOT-09:17","document_reference":"FOT-09:17","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"RESERVADO","display_order":2},{"passage_title":"El caso de las 9:17","record_type":"timeline","occurred_at":"Poco después de las 21:30","title":"Movimiento observado por mantenimiento","body":"Un empleado de mantenimiento afirmó haber visto movimiento de maletas poco después de las 21:30. La lectura no reproduce una declaración escrita independiente del empleado.","source":"Relato incluido en la lectura; declaración escrita no reproducida","sender":"Relato de mantenimiento","recipient":"","subject":"","suspect_name":null,"evidence_title":null,"evidence_code":"","document_reference":"","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"RESERVADO","display_order":3},{"passage_title":"El caso de las 9:17","record_type":"timeline","occurred_at":"21:40","title":"Entrada 4589 en el libro de equipajes","body":"El libro de equipajes registra un traslado a las 21:40 y anota a M. Rojas en la columna «Responsable». El campo no demuestra por sí solo quién movió el equipaje.","source":"Libro de equipajes · entrada 4589","sender":"Archivo documental","recipient":"","subject":"","suspect_name":null,"evidence_title":"Registro de equipajes","evidence_code":"REG-4589","document_reference":"LIB-EQ-4589","page_number":"Folio 4589","seal":"CONFIDENCIAL","signature_note":"Recreación visual de registro; no acredita identidad del ejecutor.","classification":"RESERVADO","display_order":4},{"passage_title":"El caso de las 9:17","record_type":"timeline","occurred_at":"22/04/1934","title":"Declaración firmada de Julián Herrera","body":"Se recuperó una declaración escrita y firmada por Herrera al día siguiente de la desaparición. En ella explica el cierre y sostiene que después no hubo movimientos.","source":"Declaración del encargado · 22/04/1934","sender":"Archivo documental","recipient":"","subject":"","suspect_name":null,"evidence_title":"Declaración del encargado","evidence_code":"DEC-HERRERA","document_reference":"DEC-22-04-1934","page_number":"22/04/1934","seal":"CONFIDENCIAL","signature_note":"La firma identifica al declarante; no garantiza por sí sola la exactitud del recuerdo.","classification":"RESERVADO","display_order":5},{"passage_title":"El último testigo","record_type":"email","occurred_at":"19:12","title":"Correo referido: Las cifras que no quieren mostrar","body":"La crónica refiere que Vera Pardo remitió a la emisora un correo con una fotografía de una tabla de mediciones. La imagen no era el informe completo. Esta ficha resume el dato descrito en la lectura; no reproduce el mensaje original.","source":"Correo remitido a la emisora comunitaria","sender":"Vera Pardo","recipient":"Emisora comunitaria","subject":"Las cifras que no quieren mostrar","suspect_name":"Vera Pardo","evidence_title":null,"evidence_code":"","document_reference":"COR-19:12","page_number":"","seal":"COPIA DE CONSULTA","signature_note":"","classification":"ÍNDICE DOCUMENTAL","display_order":1},{"passage_title":"El último testigo","record_type":"message","occurred_at":"18:41","title":"Pista: impresión desde PL-02","body":"El sistema registró un trabajo de 12 páginas desde PL-02 a las 18:41. El equipo está identificado, pero no hay un usuario asociado al trabajo. La pista acredita una impresión, no quién la realizó.","source":"Registro del sistema de impresión","sender":"Archivo técnico","recipient":"","subject":"","suspect_name":null,"evidence_title":null,"evidence_code":"PL-02","document_reference":"PL-02 · 18:41","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"RESERVADO","display_order":1},{"passage_title":"El último testigo","record_type":"message","occurred_at":"18:28–18:53","title":"Pista: intervalo sin videovigilancia","body":"El informe de mantenimiento confirma que la cámara del pasillo dejó de grabar entre las 18:28 y las 18:53 por una falla de alimentación. No identifica quién causó el corte.","source":"Informe de mantenimiento","sender":"Seguridad del edificio","recipient":"","subject":"","suspect_name":null,"evidence_title":null,"evidence_code":"CAM-01","document_reference":"CAM-01 · 18:28–18:53","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"RESERVADO","display_order":2},{"passage_title":"El último testigo","record_type":"message","occurred_at":"Revisión posterior","title":"Pista: fragmento recuperado","body":"La hoja hallada en la papelera del equipo PL-02 coincide con la fotografía enviada por Vera Pardo. El fragmento no contiene fecha, firma ni marcas que identifiquen quién lo imprimió.","source":"Revisión técnica del equipo PL-02","sender":"Revisión documental","recipient":"","subject":"","suspect_name":null,"evidence_title":null,"evidence_code":"PL-02","document_reference":"PL-02 · fragmento","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"RESERVADO","display_order":3},{"passage_title":"El último testigo","record_type":"message","occurred_at":"18:47","title":"Pista: marca temporal de «tabla_final»","body":"La copia digital de Tomás Leal figura modificada a las 18:47. La hora podría corresponder a una sincronización automática; no demuestra por sí sola que alguien abriera el archivo en ese momento.","source":"Metadatos del archivo y declaración de Tomás Leal","sender":"Registro informático","recipient":"","subject":"","suspect_name":null,"evidence_title":null,"evidence_code":"TABLA-FINAL","document_reference":"tabla_final · 18:47","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"RESERVADO","display_order":4},{"passage_title":"El último testigo","record_type":"timeline","occurred_at":"16:40","title":"Entrega declarada del informe firmado","body":"Tomás Leal afirmó haber entregado el informe firmado a esta hora. El expediente disponible no incluye un comprobante de recepción que confirme independientemente la entrega.","source":"Declaración de Tomás Leal","sender":"Tomás Leal","recipient":"","subject":"","suspect_name":"Tomás Leal","evidence_title":null,"evidence_code":"","document_reference":"","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"REGISTRO DEL EXPEDIENTE","display_order":1},{"passage_title":"El último testigo","record_type":"timeline","occurred_at":"17:20","title":"Ingreso de Vera Pardo","body":"El registro de visitantes sitúa a Vera Pardo en Planeación a las 17:20.","source":"Registro de visitantes","sender":"Registro de visitantes","recipient":"","subject":"","suspect_name":"Vera Pardo","evidence_title":null,"evidence_code":"","document_reference":"","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"REGISTRO DEL EXPEDIENTE","display_order":2},{"passage_title":"El último testigo","record_type":"timeline","occurred_at":"17:58","title":"Salida de Vera Pardo","body":"El registro de visitantes consigna su salida a las 17:58 y no muestra un segundo ingreso.","source":"Registro de visitantes","sender":"Registro de visitantes","recipient":"","subject":"","suspect_name":"Vera Pardo","evidence_title":null,"evidence_code":"","document_reference":"","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"REGISTRO DEL EXPEDIENTE","display_order":3},{"passage_title":"El último testigo","record_type":"timeline","occurred_at":"18:10","title":"Última revisión declarada","body":"Inés Salcedo dijo haber terminado de revisar el informe y haberlo dejado completo en el segundo cajón.","source":"Versión de Inés Salcedo","sender":"Inés Salcedo","recipient":"","subject":"","suspect_name":"Inés Salcedo","evidence_title":null,"evidence_code":"","document_reference":"","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"REGISTRO DEL EXPEDIENTE","display_order":4},{"passage_title":"El último testigo","record_type":"timeline","occurred_at":"18:18","title":"Salida de Inés Salcedo","body":"Una compañera la sitúa saliendo del edificio. No pudo precisar si llevaba la carpeta habitual.","source":"Testimonio de una compañera","sender":"Inés Salcedo","recipient":"","subject":"","suspect_name":"Inés Salcedo","evidence_title":null,"evidence_code":"","document_reference":"","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"REGISTRO DEL EXPEDIENTE","display_order":5},{"passage_title":"El último testigo","record_type":"timeline","occurred_at":"18:28–18:53","title":"Interrupción de la cámara del pasillo","body":"La cámara dejó de grabar durante este intervalo por una falla de alimentación eléctrica, según el informe de mantenimiento. El registro no identifica quién provocó la falla.","source":"Informe de mantenimiento","sender":"Archivo de investigación","recipient":"","subject":"","suspect_name":null,"evidence_title":null,"evidence_code":"","document_reference":"","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"REGISTRO DEL EXPEDIENTE","display_order":6},{"passage_title":"El último testigo","record_type":"timeline","occurred_at":"18:32","title":"Apertura de la puerta lateral","body":"El libro de novedades registra que la puerta lateral fue abierta durante el turno de Mateo Rincón. El asiento no demuestra por sí solo que alguien entrara al archivo.","source":"Libro de novedades de vigilancia","sender":"Mateo Rincón","recipient":"","subject":"","suspect_name":"Mateo Rincón","evidence_title":null,"evidence_code":"","document_reference":"","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"REGISTRO DEL EXPEDIENTE","display_order":7},{"passage_title":"El último testigo","record_type":"timeline","occurred_at":"18:41","title":"Trabajo de impresión desde PL-02","body":"El sistema registró la impresión de 12 páginas desde el equipo PL-02. El registro identifica el equipo, pero no a la persona que lo utilizó.","source":"Registro del sistema de impresión","sender":"Archivo de investigación","recipient":"","subject":"","suspect_name":null,"evidence_title":null,"evidence_code":"","document_reference":"","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"REGISTRO DEL EXPEDIENTE","display_order":8},{"passage_title":"El último testigo","record_type":"timeline","occurred_at":"18:47","title":"Modificación de «tabla_final»","body":"El archivo de trabajo figura modificado a las 18:47. Tomás Leal explicó que la hora podía corresponder a una actualización automática de la carpeta sincronizada.","source":"Metadatos del archivo y versión de Tomás Leal","sender":"Tomás Leal","recipient":"","subject":"","suspect_name":"Tomás Leal","evidence_title":null,"evidence_code":"","document_reference":"","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"REGISTRO DEL EXPEDIENTE","display_order":9},{"passage_title":"El último testigo","record_type":"timeline","occurred_at":"19:12","title":"Correo remitido a la emisora","body":"Vera Pardo envió un correo con el asunto «Las cifras que no quieren mostrar». El mensaje incluía una fotografía de una tabla de mediciones, no el informe completo.","source":"Correo remitido a la emisora comunitaria","sender":"Registro de visitantes","recipient":"","subject":"","suspect_name":"Vera Pardo","evidence_title":null,"evidence_code":"","document_reference":"","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"REGISTRO DEL EXPEDIENTE","display_order":10},{"passage_title":"El último testigo","record_type":"timeline","occurred_at":"D+1 · 06:50","title":"Hallazgo de la carpeta incompleta","body":"A la mañana siguiente se encontró la carpeta, pero faltaban el informe firmado y las páginas donde aparecían las mediciones de la quebrada La Honda.","source":"Relato del hallazgo en la crónica","sender":"Archivo de investigación","recipient":"","subject":"","suspect_name":null,"evidence_title":null,"evidence_code":"","document_reference":"","page_number":"","seal":"CONFIDENCIAL","signature_note":"","classification":"REGISTRO DEL EXPEDIENTE","display_order":11}]'::jsonb) as x(
    passage_title text, record_type text, occurred_at text, title text, body text,
    source text, sender text, recipient text, subject text, suspect_name text,
    evidence_title text, evidence_code text, document_reference text, page_number text,
    seal text, signature_note text, classification text, display_order integer
  )
)
insert into public.game_case_records (
  passage_id,record_type,occurred_at,title,body,source,sender,recipient,subject,
  suspect_id,evidence_asset_id,evidence_code,document_reference,page_number,seal,
  signature_note,classification,display_order
)
select p.id,e.record_type,e.occurred_at,e.title,e.body,e.source,e.sender,e.recipient,e.subject,
       s.id,a.id,e.evidence_code,e.document_reference,e.page_number,e.seal,
       e.signature_note,e.classification,e.display_order
from entries e
join public.game_reading_passages p
  on p.game_key='archivo-oculto' and p.title=e.passage_title and p.status='published'
left join public.game_reading_suspects s
  on s.passage_id=p.id and s.name=e.suspect_name
left join public.game_evidence_assets a
  on a.passage_id=p.id and a.title=e.evidence_title
where not exists (
  select 1 from public.game_case_records r
  where r.passage_id=p.id and r.record_type=e.record_type and r.title=e.title
);
